// Distortion: Drive, wet mix and output level. This is the Distortion primitive, distinct from legacy WaveShaper.
// Audition composition of public Rust primitives; not an instrument parity claim.
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  distortion as distortionDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    distortion_drive: {
      "path": "/primitives/distortion/node/0",
      "label": "Drive",
      "group": "Distortion",
      "min": 1,
      "max": 30,
      "default": 4
    },
    distortion_wetMix: {
      "path": "/primitives/distortion/node/1",
      "label": "Wet mix",
      "group": "Distortion",
      "min": 0,
      "max": 1,
      "default": 1
    },
    distortion_output: {
      "path": "/primitives/distortion/node/2",
      "label": "Output",
      "group": "Distortion",
      "min": 0,
      "max": 2,
      "default": 0.5
    },
  };

  // Audio inputs and outputs — the host supplies the external audio input.
  const graph = createGraphWorkspace().setInputSource('external');
  const input = graph.input.output('out');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const distortion = graph.add(distortionDefinition.type, {"id":4});
  graph.registerInstance('/primitives/distortion/node', distortion);
  distortion.parameter('drive').expose(controls.distortion_drive);
  distortion.parameter('wetMix').expose(controls.distortion_wetMix);
  distortion.parameter('output').expose(controls.distortion_output);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(input, distortion.input('audio'));
  graph.connect(distortion.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.distortion_drive,
    controls.distortion_wetMix,
    controls.distortion_output
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
